# Generate the test protos on Windows with the embeddedproto command from the virtual environment
# and check that a header was written for every one of them. On Linux the CMake build generates
# and compiles the same files, on Windows the C++ tests are not built so this is the check that the
# installed command works. Run python install.py first.

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

# Run from the repository root regardless of the directory the script is called from.
Set-Location (Join-Path $PSScriptRoot '..')

$embeddedproto = 'venv\Scripts\embeddedproto.exe'
$protoDir = 'test\proto'
$outDir = 'build\generated'
$optionsFile = 'test\options\embedded_proto_test.options.json'

if (-not (Test-Path $embeddedproto))
{
  Write-Host "$embeddedproto was not found, run python install.py first."
  exit 1
}

# All proto files as paths relative to the proto directory, the generated header of each one ends
# up at the same relative path in the output directory.
$protoRoot = (Resolve-Path $protoDir).Path
$protos = @(Get-ChildItem -Path $protoDir -Recurse -Filter '*.proto' |
  ForEach-Object { $_.FullName.Substring($protoRoot.Length + 1) })

if (Test-Path $outDir)
{
  Remove-Item -Recurse -Force $outDir
}
New-Item -ItemType Directory -Path $outDir | Out-Null

$files = @($protos | ForEach-Object { Join-Path $protoDir $_ })
& $embeddedproto -I $protoDir "--eams_out=$outDir" "--eams_opt=options_file=$optionsFile" @files
if ($LASTEXITCODE -ne 0)
{
  Write-Host "embeddedproto failed with exit code $LASTEXITCODE."
  exit 1
}

$missing = @()
foreach ($proto in $protos)
{
  $header = Join-Path $outDir ($proto -replace '\.proto$', '.h')
  if ((-not (Test-Path $header)) -or ((Get-Item $header).Length -eq 0))
  {
    $missing += $header
  }
}

if ($missing.Count -gt 0)
{
  Write-Host "No header was generated for:"
  $missing | ForEach-Object { Write-Host "  $_" }
  exit 1
}

Write-Host "Generated a header for all $($protos.Count) proto files in $outDir."
exit 0
